const state={crosshair:false,indicatorTab:'全部',indicatorQuery:'',previewTime:'morning',noticeDismissed:false,page:'watch',selected:'gold',frame:'H1',theme:'dark',scene:'normal',group:'全部',watch:['gold','eur','btc','silver','nasdaq','cn'],groups:[{name:'重点关注',ids:['gold','eur','btc']},{name:'外汇贵金属',ids:['gold','eur','silver']}],indicators:['EMA 20','EMA 60'],indicatorPeriods:{'EMA 20':20,'EMA 60':60,'布林带':20},rules:structuredClone(fixtureRules),alertFilter:'全部',centerTab:'平台',centerSource:'全部',centerSearch:'',search:'',searchSource:'全部',eventAck:false,sheet:null,dirty:false,edit:null,mode:'触价'};
// Representative catalog fixtures; formal App uses the professional chart runtime catalog.
const studyCatalog=[
 ['EMA 20','指数移动平均线','EMA','主图'],['EMA 60','指数移动平均线（第二条）','EMA','主图'],['布林带','布林带','Bollinger Bands BB','主图'],
 ['SMA','简单移动平均线','Moving Average SMA','主图'],['WMA','加权移动平均线','Moving Average Weighted WMA','主图'],['RSI','相对强弱指数','Relative Strength Index RSI','副图'],['MACD','指数平滑异同均线','MACD','副图'],['ATR','平均真实波幅','Average True Range ATR','副图'],['Stochastic','随机指标','Stochastic STOCH','副图'],['CCI','顺势指标','Commodity Channel Index CCI','副图'],['OBV','能量潮','On Balance Volume OBV','副图'],['Volume','成交量','Volume','副图']
].map(([id,label,aliases,pane])=>({id,label,aliases,pane,source:'内置'}));
const defaultPeriod=id=>id==='MACD'?12:id==='RSI'||id==='ATR'?14:20;
const getInstrument=id=>instruments.find(i=>i.id===id);
const current=()=>getInstrument(state.selected);
const isUp=i=>i.pct.startsWith('+');
const tint=i=>isUp(i)?'up':'down';
const cached=()=>['offline','loading','error'].includes(state.scene);
const quoteMuted=i=>cached()||(state.scene==='stale'&&['gold','eur','gold-self','gold-native','eur-self','eur-native'].includes(i.id));
const transport=()=>['offline','offline-empty'].includes(state.scene)?'SSE 重连中':['loading','cold'].includes(state.scene)?'SSE 连接中':state.scene==='error'?'数据重试中':'SSE 已连接';
const connectionCopy=()=>cached()?'上次数据 · 正在重新确认':state.scene==='cold'?'正在读取':'最近通信 '+demoClock();

const indicatorLabel=x=>x.startsWith('EMA ')?'EMA '+state.indicatorPeriods[x]:x;
