function action(a,text,id='',cls='soft-btn'){return `<button type="button" class="${cls}" data-action="${a}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`}
function iconButton(a,name,ico,id=''){return `<button type="button" class="icon-btn" data-action="${a}" data-id="${esc(id)}" aria-label="${name}">${icon(ico)}</button>`}
function badge(status){return `<span class="badge ${status==='issue'?'warn':['paused','expired','done'].includes(status)?'gray':''}">${status==='issue'?'! ':status==='active'?'● ':''}${labels[status]}</span>`}
function tabs(values,selected,a){return `<div class="segmented">${values.map(v=>`<button class="${selected===v?'active':''}" data-action="${a}" data-id="${v}" aria-pressed="${selected===v}">${v}</button>`).join('')}</div>`}
function details(rows){return `<dl class="details-list">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`}
function hint(text){return `<p class="sheet-hint">${text}</p>`}
// Design-only timestamps and series. These helpers do not change production calendars.
const previewTimes={morning:'2026-11-11T01:41:08Z',europe:'2026-11-11T09:41:08Z',america:'2026-11-11T14:41:08Z'};
const demoNow=()=>Date.parse(previewTimes[state.previewTime]);
const demoClock=(lag=0)=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(demoNow()-lag);
const sparkRule=i=>['gold','gold-native','gold-self','eur','eur-native','eur-self','jpy'].includes(i.id)?'NY17':'UTC0';
function zoneParts(ms,zone){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(ms).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]))}
function localInstant(y,m,d,h,zone){const wall=Date.UTC(y,m-1,d,h);let candidate=wall;for(let n=0;n<4;n++){const p=zoneParts(candidate,zone);const offset=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second)-candidate;candidate=wall-offset}return candidate}
function sparkWindow(rule,now){
 if(rule==='UTC0'){const d=new Date(now);const start=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate());return {start,end:start+86400000}}
 const p=zoneParts(now,'America/New_York');let day=new Date(Date.UTC(p.year,p.month-1,p.day));if(p.hour<17)day.setUTCDate(day.getUTCDate()-1);
 const start=localInstant(day.getUTCFullYear(),day.getUTCMonth()+1,day.getUTCDate(),17,'America/New_York');day.setUTCDate(day.getUTCDate()+1);
 return {start,end:localInstant(day.getUTCFullYear(),day.getUTCMonth()+1,day.getUTCDate(),17,'America/New_York')};
}
function activeMarkers(start,end){return ['Europe/London','America/New_York'].flatMap(zone=>{const p=zoneParts(start,zone);return [0,1,2].map(delta=>{const d=new Date(Date.UTC(p.year,p.month-1,p.day+delta));return {zone,time:localInstant(d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate(),8,zone)}}).filter(x=>x.time>=start&&x.time<end)})}
function spark(i){
 const now=demoNow(),rule=sparkRule(i),{start,end}=sparkWindow(rule,now),span=end-start;
 const missing=quoteMuted(i),last=now-(missing?75*60000:0),index=Math.max(0,instruments.indexOf(i));
 const x=t=>3+154*(t-start)/span;
 // Explicit sample timestamps for stock fixtures; no market-hours inference in rendering.
 const stockHours={nasdaq:[14.5,21],cn:[1.5,7],hk:[1.5,8]};
 const allowed=t=>{if(!stockHours[i.id])return true;const h=(t%86400000)/3600000;return h>=stockHours[i.id][0]&&h<=stockHours[i.id][1]&&!(i.id==='cn'&&h>3.5&&h<5)};
 let segments=[],segment=[];
 const append=t=>{const progress=(t-start)/span;const gap=missing&&progress>.07&&progress<.11;
 if(!allowed(t)||gap){if(segment.length)segments.push(segment);segment=[];return}
 const drift=(isUp(i)?-1:1)*(5+progress*13);const y=29+drift+Math.sin(progress*63+index)*3+Math.sin(progress*157+index*.8)*2;
 segment.push([x(t),y,t]);};
 for(let t=start;t<=last;t+=5*60000)append(t);
 if(last>=start&&last<end)append(last);if(segment.length)segments.push(segment);
 const line=segments.map(seg=>`<polyline points="${seg.map(([x,y])=>`${x.toFixed(2)},${y.toFixed(2)}`).join(' ')}" stroke="currentColor" fill="none" stroke-width="1.5" vector-effect="non-scaling-stroke" stroke-linejoin="round"/>`).join('');
 const area=segments.map(seg=>`<polygon points="${seg[0][0]},48 ${seg.map(([x,y])=>`${x},${y}`).join(' ')} ${seg.at(-1)[0]},48" fill="currentColor" opacity=".10"/>`).join('');
 const markers=rule==='NY17'?activeMarkers(start,end).map(({time,zone})=>`<line class="session-marker" data-zone="${zone}" x1="${x(time)}" x2="${x(time)}" y1="3" y2="48" stroke="var(--muted)" opacity="${time<=now?'.55':'.25'}" stroke-dasharray="2 3" vector-effect="non-scaling-stroke"/>`).join(''):'';
 const tip=segments.at(-1)?.at(-1);
 return `<svg class="spark ${missing?'muted':tint(i)}" data-rule="${rule}" data-start="${start}" data-end="${end}" data-now="${now}" data-last="${tip?.[2]||''}" viewBox="0 0 160 52" preserveAspectRatio="none" role="img" aria-label="${esc(i.name)}模拟分时图，${rule}固定窗口，未来留空${tip?'':'，本窗口暂无数据'}"><path d="M3 29H157" stroke="var(--muted)" stroke-dasharray="2 4" opacity=".25" vector-effect="non-scaling-stroke"/>${markers}${area}${line}${tip?`<ellipse cx="${tip[0]}" cy="${tip[1]}" rx="1.8" ry="1.8" fill="currentColor"/>`:''}</svg>`;
}
function notice(text,type='normal',button=''){return `<div class="status-strip ${type==='warn'?'warn':''}" role="${type==='warn'?'status':'note'}">${text}${button}</div>`}
function empty(title,description,button=''){return `<div class="state-panel"><span class="state-icon">${icon('watch')}</span><h3>${title}</h3><p>${description}</p>${button}</div>`}
function quoteRow(i){return `<button class="quote-row spark-fixed ${quoteMuted(i)?'quote-cached':''}" data-action="chart" data-id="${i.id}" aria-label="查看${i.name}图表"><span class="quote-info"><strong>${i.symbol}</strong><small>${i.name}<br>${i.kind} · ${i.source}</small></span>${spark(i)}<span class="quote-price"><strong>${num(i.price,i.dec)}</strong><span class="${quoteMuted(i)?'muted':tint(i)}">${i.pct}</span></span></button>`}
function sparkOptions(){openSheet('分时图与参考',hint('已采用中间宽幅图：外汇、黄金用 NY17，其余用 UTC0。窗口固定，未来留空；不压缩休市或缺失时间。')+`<div class="spark-choices">${[['morning','上午 · 北京时间 09:41'],['europe','欧盘 · 北京时间 17:41'],['america','美盘 · 北京时间 22:41']].map(([id,title])=>`<button type="button" data-action="preview-time" data-id="${id}" aria-pressed="${state.previewTime===id}" class="source-tile">${title}</button>`).join('')}</div>`+hint('时间按钮仅用于设计审阅，示例日期为 2026-11-11；不是真实行情回放。欧盘/美盘用两条无文字竖线表示，分别参考伦敦 08:00、纽约 08:00，并独立换算夏令时。')+hint('横向虚线示意已知的涨跌参考价，未到的时间留白；圆点表示最新有效行情。各行纵轴独立缩放，不能直接比较波动幅度。两种日界线下，同一时刻的位置不同。')+action('demo-notice','演示告警浮动通知','','soft-btn full')+`<h3 class="reference-heading">官方产品图示</h3><p class="sheet-hint">下方是原产品官方图片，仅参考信息布局。点击图片查看原图，产品名称链接到出处。</p><figure class="reference"><a href="./assets/apple-stocks.png" target="_blank" rel="noopener"><img src="./assets/apple-stocks.png" alt="Apple Stocks 官方自选列表截图，中间列为迷你走势图" width="490" height="1008"></a><figcaption><a href="https://support.apple.com/guide/iphone/check-stocks-iph1ac0b1bc/ios" target="_blank" rel="noopener">Apple Stocks · 官方使用手册 ↗</a><p>参考中间列走势、右侧价格的紧凑布局。图片归 Apple 所有。</p></figcaption></figure><figure class="reference"><a href="./assets/cmc-watchlist.jpeg" target="_blank" rel="noopener"><img src="./assets/cmc-watchlist.jpeg" alt="CoinMarketCap 官方产品宣传图，右侧为迷你走势图" width="1920" height="1920"></a><figcaption><a href="https://coinmarketcap.com/mobile/" target="_blank" rel="noopener">CoinMarketCap · 官方移动端页面 ↗</a><p>官方产品宣传图，参考走势与涨跌数字分区；不作为实盘截图。图片归 CoinMarketCap 所有。</p></figcaption></figure>`,'spark-options')}
function header(){
 $('#header').classList.toggle('watch-header',state.page==='watch');
 $('#header').classList.toggle('chart-toolbar',state.page==='chart');
 if(state.page==='chart'){
 $('#header').innerHTML=`<button type="button" class="period-picker" data-action="pick-frame" aria-label="选择图表周期，当前 ${state.frame}">${state.frame}${icon('down')}</button><div class="chart-tools"><button type="button" class="icon-btn ${state.crosshair?'tool-active':''}" data-action="crosshair" aria-label="十字线" aria-pressed="${state.crosshair}">${icon('crosshair')}</button>${iconButton('indicators','图表指标','indicators')}${iconButton('create','创建当前品种价格告警','bell')}</div>`;return;
 }

 if(state.page==='watch'){
  const offline=state.scene==='offline',loading=state.scene==='loading';
  $('#header').innerHTML=`<div class="watch-heading"><button type="button" id="group-picker" class="group-picker" data-action="groups" aria-label="选择自选分组，当前${esc(state.group)}" title="当前分组：${esc(state.group)}"><span>自选${state.group!=='全部'?`<small class="selected-group">${esc(state.group)}</small>`:''}</span>${icon('down')}</button><div class="sse-status ${offline?'disconnected':''}"><span><i class="live-dot"></i>${transport()}</span><small>${loading||state.scene==='cold'?'等待首次通信':`最近通信 ${offline?demoClock(75*60000):demoClock()}`}</small></div></div><div class="header-actions">${iconButton('search','搜索并添加品种','plus')}${iconButton('manage','管理自选','sliders')}</div>`;
  return;
 }

 const title={watch:'自选',chart:current().symbol,alerts:'告警',more:'更多',center:'数据',login:'连接守望'}[state.page];
 const back=false;
 const sub=state.page==='chart'?`${current().name} · ${current().kind} · ${current().source}`:state.page==='center'?'平台目录、自建行情与组合':state.page==='login'?'个人行情与价格提醒':cached()?connectionCopy():state.scene==='cold'?'正在读取':state.scene==='offline-empty'?'暂无本地数据':'最近通信 '+demoClock();
 let actions=state.page==='watch'?iconButton('search','搜索并添加品种','plus'):
 state.page==='chart'?iconButton('search','切换品种','search')+iconButton('watch-toggle',state.watch.includes(state.selected)?'移出自选':'加入自选',state.watch.includes(state.selected)?'check':'plus'):
 state.page==='alerts'?iconButton('create','新建价格告警','plus'):
 state.page==='center'?iconButton('sources','查看来源状态','wifi'):'';
 $('#header').innerHTML=`<div class="${back?'back-title':''}">${back?iconButton('back-page','返回更多','chevron'):''}<div><h2>${title}</h2><small>${!['chart','center','login'].includes(state.page)?'<i class="live-dot"></i>':''}${sub}</small></div></div><div class="header-actions">${actions}</div>`;
}
function nav(){ $('#nav').hidden=state.page==='login';$('#nav').innerHTML=[['watch','自选','watch'],['chart','图表','chart'],['alerts','告警','bell'],['center','数据','data'],['more','更多','more']].map(([p,t,i])=>`<button class="${state.page===p?'active':''}" data-action="page" data-id="${p}" ${state.page===p?'aria-current="page"':''}><span class="nav-icon">${icon(i)}${p==='alerts'&&state.rules.some(r=>r.status==='issue')?`<span class="nav-count" aria-label="${state.rules.filter(r=>r.status==='issue').length} 条告警需处理">${state.rules.filter(r=>r.status==='issue').length}</span>`:''}</span>${t}</button>`).join('') }
function watchPage(){
 const ids=state.group==='全部'?state.watch:state.groups.find(g=>g.name===state.group)?.ids||[];
 const rows=ids.filter(id=>state.watch.includes(id)).map(getInstrument);
 return `${rows.map(quoteRow).join('')||empty('还没有关注品种','从目录中找到你关注的品种，添加后会显示在这里。',action('search','添加品种','','primary'))}`;
}
function chartPage(){const i=current();return `<div class="chart-canvas ${quoteMuted(i)?'chart-cached':''}"><div class="chart-identity"><strong>${i.symbol}</strong><small>${i.kind} · ${i.source}${quoteMuted(i)?' · 上次行情':''}</small></div><div class="chart-legend">${state.indicators.map(x=>`<span>${indicatorLabel(x)}</span>`).join('')}</div><div class="chart-viewport ${state.crosshair?'crosshair-on':''}" tabindex="${state.crosshair?'0':'-1'}" aria-label="${state.crosshair?'十字线查看模式，可拖动或使用方向键移动，Escape 退出':'图表绘图区'}">${candles()}${state.crosshair?'<div class="demo-crosshair"><i class="cross-v"></i><i class="cross-h"></i><span class="cross-price"></span><span class="cross-time"></span></div>':''}</div></div>`}
function alertCard(r){const i=getInstrument(r.instrument);return `<article class="alert-card"><div class="alert-top"><strong>${i.symbol}</strong>${cached()?'<span class="badge gray">上次：'+labels[r.status]+'</span>':badge(r.status)}</div><div class="rule-title">${esc(r.name)}</div><div class="alert-condition">${r.relation} ${num(r.threshold,i.dec)}</div><p class="alert-meta">${r.mode==='收盘'?r.frame+' 收盘确认':'触价检测'} · 最多 ${r.count} 次<br>${r.notify?'ntfy 通知 + 站内记录':'仅站内记录'} · ${r.expiry==='不限'?'不限到期时间':r.expiry==='已到期'?'已到期':r.expiry+'后到期'}</p>${r.status==='issue'?'<div class="warn-box">行情更新中断，暂时无法确认是否触价。</div>':r.status==='waiting'?notice('规则已保存，等待服务接管。尚未确认开始检测。'):''}<div class="alert-bottom"><span>${cached()?'上次读取 09:36 · 待确认':r.status==='active'?'最近检测 09:41:08':r.status==='paused'?'暂停新的检测':r.status==='issue'?'最后行情 09:36:00':r.status==='done'?'已达到触发次数':r.status==='expired'?'不会继续检测':'等待后台确认'}</span><div>${action('rule-detail','详情',r.id,'link-btn')}${['active','issue','waiting','paused'].includes(r.status)?action('toggle-rule',r.status==='paused'?'恢复':'暂停',r.id,'link-btn'):''}</div></div></article>`}
function alertsPage(){const counts=s=>state.rules.filter(r=>r.status===s).length;const filter={'监控中':'active','需处理':'issue','已暂停':'paused','等待接管':'waiting','已到期':'expired','已完成':'done'};const rows=state.rules.filter(r=>state.alertFilter==='全部'||r.status===filter[state.alertFilter]);return `<div class="health-card"><div class="health-title">${icon('shield')}${cached()?'上次读取的监控概况':'由服务器检测价格'}</div><div class="health-stats"><div><strong>${counts('active')}</strong><small>监控中</small></div><div><strong style="color:var(--warn)">${counts('issue')}</strong><small>需要处理</small></div><div><strong class="muted">${counts('paused')}</strong><small>已暂停</small></div></div></div><div class="compact-filter">${tabs(['全部','监控中','需处理','已暂停'],state.alertFilter,'alert-filter')}${iconButton('rule-filters','更多告警筛选','sliders')}</div>${!['全部','监控中','需处理','已暂停'].includes(state.alertFilter)?`<p class="rows-note">当前筛选：${state.alertFilter}</p>`:''}${rows.map(alertCard).join('')||empty('没有这类告警','可以切换筛选，或为关注品种创建价格告警。',action('create','新建价格告警','','primary'))}${action('events',icon('history')+'触发与异常记录','','soft-btn full')}`}
function setting(ico,label,value,a){return `<button class="setting-row" data-action="${a}"><span>${icon(ico)}${label}</span><small>${value}</small>${icon('chevron')}</button>`}
function morePage(){return `<div class="profile"><span class="profile-icon">W</span><div><strong>我的守望</strong><small>个人工作区 · OPPO Find X8</small></div></div><div class="setting-group"><h3>行情与数据</h3>${setting('wifi','连接状态',state.scene==='offline'?'离线':'开发实例','connection')}</div><div class="setting-group"><h3>通知与显示</h3>${setting('bell','后台通知',state.scene==='ntfy-off'?'待配置':'ntfy','ntfy')}${setting('history','告警记录','触发与异常','events')}${setting('moon','显示主题',state.theme==='dark'?'深色':'浅色','theme')}</div><div class="setting-group"><h3>账户与应用</h3>${setting('info','关于守望','版本与使用说明','about')}${setting('external','退出登录','','logout')}</div>`}
function dataRows(){let rows=instruments.filter(i=>state.centerTab==='平台'?i.kind==='平台':state.centerTab==='组合'?i.kind==='组合':i.kind==='自建');return rows.filter(i=>(state.centerSource==='全部'||i.source===state.centerSource)&&`${i.symbol} ${i.name}`.toLowerCase().includes(state.centerSearch.toLowerCase()))}
function dataList(){const rows=dataRows();return rows.map(i=>`<button class="data-card" data-action="data-detail" data-id="${i.id}" data-kind="${state.centerTab}"><span class="data-heading"><strong>${i.symbol} · ${i.name}</strong><span class="badge">${state.centerTab}</span></span><p>${i.source} · ${state.centerTab==='自建'?'M1 基础数据 · 每日维护':state.centerTab==='组合'?'历史 + 实时 · 固定组合修订':'供应商原生行情'}<br>${cached()?'上次读取 09:36 · 待更新':state.centerTab==='平台'?'目录可查询 · 不代表已下载行情':'可用数据至 09:41 · 模拟状态'}</p><span class="data-foot"><span>${supported(i).length} 个周期 · 查看详情</span>${icon('chevron')}</span></button>`).join('')||empty('没有匹配的数据','尝试修改关键词或切换来源筛选。',action('clear-center','清除筛选','','soft-btn'))}
function centerPage(){return `${tabs(['平台','自建','组合'],state.centerTab,'center-tab')}<div class="search-field" style="margin-top:16px">${icon('search')}<input id="center-search" aria-label="搜索数据" placeholder="搜索代码或中文名称" value="${esc(state.centerSearch)}"></div><div class="mini-toolbar" style="margin-top:8px">${action('source-filter',state.centerSource==='全部'?'全部来源':state.centerSource,'','group-picker')}${action('tasks','任务与来源','','link-btn')}</div><div id="data-list">${dataList()}</div><p class="rows-note">先查询目录，再按需开图。目录记录不等于已获取全部行情。</p>`}
function loginPage(){return `<div class="login-brand"><span class="profile-icon">W</span><h3>欢迎回到守望</h3><p>${state.scene==='expired'?'会话已过期，请重新登录。成功后回到原页面。':'连接你的服务器，查看行情和价格提醒。'}</p></div><form id="login-form" novalidate><label class="field"><span>服务器地址</span><input id="server" type="url" autocomplete="url" value="https://demo.market-watch.example" aria-describedby="server-hint"></label><p class="rows-note" id="server-hint">示例地址，预览不会发起连接。</p><label class="field"><span>登录密码</span><div class="password-field"><input id="password" type="password" autocomplete="current-password" placeholder="输入任意演示密码" required><button type="button" data-action="show-password">显示</button></div></label><div id="login-error" class="form-error" role="alert" hidden></div><button class="primary full" type="submit">登录</button></form><p class="login-footer">正式版密码仅用于服务器登录，不写入 APK。登录后默认进入自选。</p>`}
function sceneContent(content){
 if(state.page==='login'||state.page==='more')return content;
 if(state.scene==='cold')return `<div class="cold-content" role="status"><p class="rows-note">正在读取…</p><div aria-hidden="true">${Array.from({length:5},()=>'<div class="skeleton"><i></i><i></i></div>').join('')}</div></div>`;
 if(state.scene==='offline-empty')return empty('暂无本地数据','连接恢复后自动读取。');
 if(state.scene==='empty'&&['watch','center','alerts'].includes(state.page))return empty(state.page==='watch'?'还没有关注品种':state.page==='alerts'?'还没有价格告警':'暂无数据',state.page==='alerts'?'选择品种并设置价格条件。':'按需选择品种，建立自己的行情清单。',action(state.page==='alerts'?'create':'search',state.page==='alerts'?'新建价格告警':'搜索品种','','primary'));
 return content;
}
function render(){header();nav();$('#device').dataset.page=state.page;$('#device').dataset.scene=state.scene;$('#device').dataset.theme=state.theme;$('#theme').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#theme').setAttribute('aria-label',state.theme==='dark'?'切换浅色主题':'切换深色主题');const pages={watch:watchPage,chart:chartPage,alerts:alertsPage,more:morePage,center:centerPage,login:loginPage};$('#screen').innerHTML=sceneContent(pages[state.page]());$('#review-page').value=state.page;$('#review-scene').value=state.scene;positionSheet();paintAlertNotice();paintOperation();if(state.crosshair&&state.page==='chart')paintCrosshair()}
function paintAlertNotice(){const n=$('#alert-notice');const count=state.rules.filter(r=>r.status==='issue').length;n.hidden=state.noticeDismissed||!count||state.page!=='watch'||state.scene!=='normal';n.innerHTML=`<div><strong>${count} 条告警需要处理</strong><p>EURUSD 行情中断，价格检测受影响。</p></div>${action('view-notice','查看','','link-btn')}${iconButton('dismiss-notice','关闭告警提醒','close')}`;n.style.top=($('#header').offsetTop+$('#header').offsetHeight+4)+'px'}
function navigate(p,push=true){pageScroll[state.page]=$('#screen').scrollTop;if(p!==state.page)state.noticeDismissed=true;if(p==='login'&&state.page!=='login')routeBeforeLogin=state.page;if(p!=='chart')state.crosshair=false;state.page=p;if(push)history.pushState({page:p},'',urlFor(p));render();$('#screen').scrollTop=pageScroll[p]||0}
function urlFor(p){const u=new URL(location.href);u.searchParams.set('page',p);return u}
function openChart(id){state.crosshair=false;state.selected=id;if(!supported(current()).includes(state.frame))state.frame=supported(current())[0];closeAll();navigate('chart');saveChartLayout()}
function positionSheet(){if(!$('#sheet').open)return;const r=$('#device').getBoundingClientRect();Object.assign($('#sheet').style,{position:'fixed',left:r.left+'px',right:'auto',top:'auto',bottom:Math.max(0,innerHeight-r.bottom)+'px',width:r.width+'px',maxWidth:r.width+'px',maxHeight:Math.min(r.height*.94,innerHeight-18)+'px'})}
function snapshotSheet(){return {html:$('#sheet-content').innerHTML,type:state.sheet,dirty:state.dirty,scroll:$('#sheet').scrollTop,fields:[...$('#sheet').querySelectorAll('input,select,textarea')].map(n=>({id:n.id,value:n.value,checked:n.checked}))}}
function openSheet(title,body,type='info',push=true){operationMessage=null;paintOperation();if($('#sheet').open&&push)sheetStack.push(snapshotSheet());state.sheet=type;state.dirty=false;$('#sheet-content').innerHTML=`<div class="sheet-head"><div>${sheetStack.length?iconButton('sheet-back','返回上一级','chevron',''):''}<h2 id="sheet-title">${title}</h2></div>${iconButton('close-sheet','关闭','close')}</div><div class="sheet-body">${body}</div>`;$('#sheet-content .sheet-head .icon-btn')?.classList.toggle('sheet-back',sheetStack.length>0);if(!$('#sheet').open)$('#sheet').showModal();positionSheet();$('#sheet').scrollTop=0;paintToast();}
function restoreSheet(){operationMessage=null;paintOperation();const last=sheetStack.pop();if(!last)return closeAll();$('#sheet-content').innerHTML=last.html;state.sheet=last.type;state.dirty=last.dirty;last.fields.forEach(f=>{const el=f.id?document.getElementById(f.id):null;if(el){el.value=f.value;if('checked'in el)el.checked=f.checked}});$('#sheet').scrollTop=last.scroll;positionSheet()}
function closeAll(){operationMessage=null;paintOperation();sheetStack.length=0;state.sheet=null;state.dirty=false;$('#sheet').close();paintToast()}
function askClose(back=false){if(state.dirty){openSheet('放弃本次修改？',hint('更改尚未提交。放弃后不会恢复草稿，已保存的数据保持不变。')+`<div class="sheet-actions">${action('keep-editing','继续编辑','','primary full')}${action(back?'discard-back':'discard-close','放弃修改','','soft-btn full')}</div>`,'discard');}else if(back)restoreSheet();else closeAll()}
function paintToast(){document.querySelector('.sheet-feedback')?.remove();$('#toast').hidden=!toastMessage||$('#sheet').open;if(!toastMessage)return;const html=`<span>${esc(toastMessage)}</span>${undo?action('undo','撤销','','plain'):''}`;$('#toast').innerHTML=html;if($('#sheet').open){const el=document.createElement('div');el.className='sheet-feedback';el.setAttribute('role','status');el.innerHTML=html;$('#sheet-content').append(el)}}
function toast(message,undoFn=null){clearTimeout(toastTimer);undo=undoFn;toastMessage=message;paintToast();toastTimer=setTimeout(()=>{toastMessage=null;undo=null;paintToast()},undoFn?8000:4000)}
let operationMessage=null;
function paintOperation(){document.querySelectorAll('.operation-feedback').forEach(x=>x.remove());const global=$('#operation-notice');global.hidden=!operationMessage||$('#sheet').open;if(!operationMessage)return;const html=`<div><strong>${esc(operationMessage.title)}</strong><p>${esc(operationMessage.text)}</p>${operationMessage.actions||''}${['offline','save-error','error'].includes(state.scene)?action('demo-recover','审阅：恢复连接','','preview-recover'):''}</div>${iconButton('dismiss-operation','关闭操作提醒','close')}`;global.innerHTML=$('#sheet').open?'':html;global.style.top=($('#header').offsetTop+$('#header').offsetHeight+4)+'px';if($('#sheet').open){const el=document.createElement('div');el.className='operation-feedback';el.setAttribute('role','alert');el.innerHTML=html;$('#sheet-content .sheet-head').after(el);$('#sheet').scrollTop=0}}
function operation(title,text,actions=''){state.noticeDismissed=true;paintAlertNotice();operationMessage={title,text,actions};paintOperation()}
function markUnsubmitted(){const form=$('#rule-form')||$('#group-form')||$('#login-form');if(!form)return;let note=form.querySelector('.submit-status');if(!note){note=document.createElement('p');note.className='submit-status';note.setAttribute('role','status');const anchor=form.querySelector('.sheet-actions')||form.querySelector('button[type=submit]');anchor.before(note)}note.textContent='尚未保存 · 本次输入已保留'}
function submissionFailure(kind='save'){markUnsubmitted();if(kind==='conflict')return operation('尚未保存','另一端已修改该数据。本次输入保留。',action('inspect-conflict','查看最新','','link-btn'));operation('提交失败','本次输入已保留，请稍后重试。',action('retry-submit','重试','','link-btn'))}
// One preview-only chart preference record, isolated from real application storage.
const layoutDB=new Promise((resolve,reject)=>{const r=indexedDB.open('mw-android-preview-a07',1);r.onupgradeneeded=()=>r.result.createObjectStore('preferences');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
let layoutWrites=Promise.resolve();
function layoutRecord(){return {selected:state.selected,frame:state.frame,indicators:[...state.indicators],indicatorPeriods:{...state.indicatorPeriods}}}
function layoutTransaction(mode,run){return layoutDB.then(db=>new Promise((resolve,reject)=>{const tx=db.transaction('preferences',mode);let value;const req=run(tx.objectStore('preferences'));req.onsuccess=()=>value=req.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)}))}
function saveChartLayout(){const record=layoutRecord();layoutWrites=layoutWrites.catch(()=>{}).then(()=>layoutTransaction('readwrite',s=>s.put(record,'chart'))).catch(()=>operation('设置未能记住','当前可继续使用，重新打开后可能无法保留。'));return layoutWrites}
async function restoreChartLayout(){try{const r=await layoutTransaction('readonly',s=>s.get('chart'));if(r&&getInstrument(r.selected)&&supported(getInstrument(r.selected)).includes(r.frame)&&Array.isArray(r.indicators)&&r.indicators.every(x=>studyCatalog.some(s=>s.id===x))&&r.indicatorPeriods&&r.indicators.every(x=>Number.isInteger(r.indicatorPeriods[x])&&r.indicatorPeriods[x]>=2&&r.indicatorPeriods[x]<=500))Object.assign(state,r)}catch{operation('本地存储不可用','本次使用默认图表设置。')}render()}
async function clearChartLayout(){await layoutWrites;try{await layoutTransaction('readwrite',s=>s.delete('chart'));return true}catch{operation('本地设置未能清除','请重试。');return false}}
function filters(list,currentValue,a){return list.map(v=>`<button class="source-tile" data-action="${a}" data-id="${v}" aria-pressed="${v===currentValue}">${v}${v===currentValue?' ✓':''}</button>`).join('')}
function searchSheet(reset=true){if(reset){state.search='';state.searchSource='全部'}openSheet('搜索品种',`<div class="search-field">${icon('search')}<input id="search-input" placeholder="代码或中文名称" aria-label="代码或中文名称" value="${esc(state.search)}" autocomplete="off"></div><div class="source-filters">${['全部',...sources].map(s=>`<button data-action="search-source" data-id="${s}" class="${s===state.searchSource?'active':''}" aria-pressed="${s===state.searchSource}">${s}</button>`).join('')}</div><p class="rows-note">示例目录 · 正式版读取服务器维护清单</p><div id="search-results"></div>`,'search',reset);searchResults()}
function membership(id){return state.group==='全部'?state.watch.includes(id):!!state.groups.find(g=>g.name===state.group)?.ids.includes(id)}
function searchResults(){const rows=instruments.filter(i=>(state.searchSource==='全部'||state.searchSource===i.source)&&`${i.symbol} ${i.name}`.toLowerCase().includes(state.search.toLowerCase()));$('#search-results').innerHTML=rows.map(i=>`<div class="search-row"><div class="info"><strong>${i.symbol} · ${i.name}</strong><small>${i.kind} · ${i.source}<br>${supported(i).join(' / ')}</small></div>${action('add-watch',membership(i.id)?'已添加':state.group==='全部'?'+ 自选':'+ 分组',i.id,'soft-btn')}${action('data-detail','详情',i.id,'link-btn')}${action('chart','开图',i.id,'link-btn')}</div>`).join('')||'<p class="empty-inline">没有匹配品种。尝试其他代码、中文名称或来源。</p>';}
function groups(){openSheet('自选分组',`<div class="data-source-grid">${filters(['全部',...state.groups.map(g=>g.name)],state.group,'pick-group')}</div><div class="sheet-actions">${action('new-group','新建分组','','soft-btn full')}${state.group!=='全部'?action('rename-group','重命名当前分组','','soft-btn full'):''}${state.group!=='全部'?action('delete-group','删除当前分组','','link-btn full'):''}</div>`,'groups')}
function manage(push=true){const ids=state.group==='全部'?state.watch:state.groups.find(g=>g.name===state.group)?.ids||[];openSheet('管理自选',hint(`当前分组：${esc(state.group)}。用上下按钮调整顺序，移除后可撤销。`)+ids.map((id,n)=>{const i=getInstrument(id);return `<div class="manage-row"><div class="info"><strong>${i.symbol}</strong><small>${i.name}</small></div><div class="list-actions"><button data-action="move-up" data-id="${id}" ${n===0?'disabled':''} aria-label="上移${i.name}">↑</button><button data-action="move-down" data-id="${id}" ${n===ids.length-1?'disabled':''} aria-label="下移${i.name}">↓</button><button class="remove" data-action="remove-watch" data-id="${id}">移除</button></div></div>`}).join('')+`<div class="sheet-actions">${action('close-sheet','完成','','primary full')}</div>`,'manage',push)}
function dataDetail(id,kind){const i=getInstrument(id);kind=kind||i.kind;const f=supported(i);openSheet('行情详情',`<h3 style="font-size:20px">${i.symbol} · ${i.name}</h3><p class="rows-note">${kind} · ${i.source} · 预览数据</p>${details([['数据来源',i.source],['系列类型',kind],['数据状态',cached()?'上次读取 · 当前待确认':kind==='平台'?'可查询目录，尚未下载全部历史':'已有可用数据 · 模拟状态'],['维护方式',kind==='自建'?'每日维护':kind==='组合'?'历史数据 + 实时数据':'按需查询'],['更新时间','2026-11-11 09:41:08'],...(kind==='组合'?[['组合修订','固定修订 r3（示例）'],['组成','自建历史 → OANDA 实时尾部']]:[])])}<h3 style="font-size:14px;margin:18px 0 12px">可用周期</h3><div class="chip-list">${f.map(x=>`<span class="period-chip">${x}</span>`).join('')}</div><p class="rows-note">正式版按该系列的实际支持情况显示。目录存在不代表行情已经完整获取。</p><div class="sheet-actions">${action('choose-frame','打开图表',id,'primary full')}${action('add-watch',membership(id)?'已加入自选':state.group==='全部'?'加入自选':'加入当前分组',id,'soft-btn full')}${action('maintenance-info','查看维护信息',id,'link-btn full')}</div>`,'data-detail')}
function ruleDetail(id){const r=state.rules.find(r=>r.id===Number(id));const i=getInstrument(r.instrument);openSheet('告警详情',`${cached()?'<span class="badge gray">上次：'+labels[r.status]+'</span>':badge(r.status)}<h3 style="font-size:20px;margin-top:16px">${esc(r.name)}</h3>${details([['品种',i.symbol+' · '+i.kind+' · '+i.source],['触发条件',r.relation+' '+num(r.threshold,i.dec)],['检测方式',r.mode==='收盘'?r.frame+' 收盘确认':'触价检测'],['触发上限','最多 '+r.count+' 次'],['到期',r.expiry],['手机通知',r.notify?'ntfy':'关闭，保留站内记录'],['最近检测',cached()?'上次读取 09:36 · 当前待确认':r.status==='active'?'09:41:08':r.status==='waiting'?'尚未接管':'09:36:00']])}${r.status==='issue'?notice('行情已中断，不能确认期间是否触价。','warn',action('issue','查看原因与处理','','link-btn')):''}<div class="sheet-actions">${action('edit-rule','编辑价格告警',r.id,'primary full')}${action('chart','查看对应行情',i.id,'soft-btn full')}${action('archive-rule','归档告警',r.id,'link-btn full')}</div>`,'rule-detail')}
function formCreate(id=null){
 const r=id?state.rules.find(r=>r.id===Number(id)):null;
 if(r)state.selected=r.instrument;
 const i=current();if(!i.alert){return openSheet('当前系列暂不可创建',hint('本预览仅为 XAUUSD、EURUSD 组合行情演示价格告警。正式版必须按服务器能力显示支持范围。')+action('choose-alert-symbol','选择其他品种','','primary full'),'capability')}
 state.edit=r?.id||null;state.mode=r?.mode||'触价';
 openSheet(r?'编辑价格告警':'新建价格告警',`<p class="sheet-hint"><strong>${i.symbol} · ${i.name}</strong><br>${i.kind} · ${i.source} · 当前模拟价 ${num(i.price,i.dec)}</p><form id="rule-form" novalidate><label class="field"><span>触发条件</span><select id="relation">${['向上穿越','向下穿越','任意穿越'].map(x=>`<option ${r?.relation===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>目标价格</span><input id="threshold" type="number" inputmode="decimal" step="any" min="0.000001" value="${r?.threshold||(i.id==='gold'?2700:1.09)}" aria-describedby="price-error" required><small id="price-error" class="error-field"></small></label><div class="field"><span>检测方式</span><div class="choice-row">${['触价','收盘'].map(x=>`<button type="button" data-action="mode" data-id="${x}" class="${state.mode===x?'active':''}" aria-pressed="${state.mode===x}">${x}<small>${x==='触价'?'价格穿越时检测':'已收盘 K 线确认'}</small></button>`).join('')}</div></div><label class="field" id="frame-field" ${state.mode==='触价'?'hidden':''}><span>确认周期</span><select id="rule-frame">${frames.map(f=>`<option ${f===(r?.frame||state.frame)?'selected':''}>${f}</option>`).join('')}</select></label><div class="field-row"><label class="field"><span>最多触发</span><select id="trigger-count">${[1,2,3].map(x=>`<option value="${x}" ${r?.count===x?'selected':''}>${x===1?'仅一次':x+' 次'}</option>`).join('')}</select></label><label class="field"><span>到期时间</span><select id="expiry">${['不限','1 天','1 周','1 月','自定义'].map(x=>`<option ${r?.expiry===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field" id="custom-expiry" hidden><span>到期时刻 · UTC</span><input id="expiry-at" type="datetime-local"><small id="expiry-error" class="error-field"></small></label><label class="toggle-row">通过 ntfy 发送手机通知<input id="notify" type="checkbox" ${(r?r.notify:state.scene!=='ntfy-off')?'checked':''} aria-label="通过 ntfy 发送手机通知"></label>${state.scene==='ntfy-off'?notice('ntfy 尚未配置。可关闭手机通知，仅保留站内记录。','warn'):''}<details class="form-detail"><summary>更多设置 <small>名称、备注与迟到通知</small></summary><label class="field"><span>告警名称</span><input id="rule-name" maxlength="80" value="${esc(r?.name||i.name+'价格提醒')}"></label><label class="field"><span>备注</span><textarea id="rule-message" maxlength="500" placeholder="可选，用来记录设置提醒的原因">${esc(r?.message||'')}</textarea></label><label class="field"><span>迟到触发结果</span><select id="late"><option value="log_only">仅记入记录</option><option value="notify" ${r?.late==='notify'?'selected':''}>仍发送通知</option></select></label></details><p class="form-notice">规则保存后由服务器接管。创建时价格已在目标一侧，不会因此立即触发；后续穿越才按条件检测。</p><div id="form-error" class="form-error" role="alert" hidden></div><div class="sheet-actions"><button type="submit" class="primary full">${r?'保存修改':'创建告警'}</button></div></form>`,'rule-form');
}
