document.addEventListener('change',e=>{if(['rule-form','group-form','study-settings'].includes(state.sheet))state.dirty=true;if(e.target.id==='expiry')$('#custom-expiry').hidden=e.target.value!=='自定义';});
document.addEventListener('submit',async e=>{
 if(e.target.id==='study-form'){e.preventDefault();const n=Number($('#study-period').value),id=e.target.dataset.id;if(!Number.isInteger(n)||n<2||n>500){$('#study-error').textContent='请输入 2–500 的整数';return}state.indicatorPeriods[id]=n;state.dirty=false;restoreSheet();render();$('#study-results').innerHTML=studyRows();return saveChartLayout()}

 if(e.target.id==='rule-form')return submitRule(e);
 if(e.target.id==='group-form'){e.preventDefault();const value=$('#group-name').value.trim();const renaming=e.target.dataset.rename==='true';if(['offline','offline-empty','save-error','conflict'].includes(state.scene))return submissionFailure(state.scene==='conflict'?'conflict':'save');if(!value||value==='全部'||state.groups.some(g=>g.name===value&&(!renaming||g.name!==state.group))){$('#group-error').hidden=false;$('#group-error').textContent='请输入不重复的分组名称（1–20 字）。';return}if(renaming)state.groups.find(g=>g.name===state.group).name=value;else state.groups.push({name:value,ids:[]});state.group=value;state.dirty=false;closeAll();render();return toast('分组已保存')}
 if(e.target.id==='login-form'){e.preventDefault();const server=$('#server'),pwd=$('#password'),error=$('#login-error');let valid=false;try{const u=new URL(server.value);valid=u.protocol==='https:'&&!u.username&&!u.password&&u.pathname==='/'}catch{}if(!valid||!pwd.value){error.hidden=false;error.textContent=!valid?'请输入有效的 HTTPS 服务器地址，不包含登录信息或路径。':'请输入演示密码。';(!valid?server:pwd).focus();return}const button=e.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='正在登录…';await new Promise(r=>setTimeout(r,450));if(['error','offline','save-error'].includes(state.scene)){button.disabled=false;button.textContent='登录';markUnsubmitted();return operation('登录失败','暂时无法连接服务器，请检查地址和网络。',action('retry-submit','重试','','link-btn'))}state.scene='normal';navigate(routeBeforeLogin);toast('已进入演示工作区，未发送密码')}
});
$('#sheet').addEventListener('cancel',e=>{e.preventDefault();askClose()});
$('#sheet').addEventListener('click',e=>{if(e.target!==$('#sheet'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)askClose()});
$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';render()};
$('#review-page').onchange=e=>{closeAll();navigate(e.target.value)};
$('#review-scene').onchange=e=>{closeAll();state.scene=e.target.value;if(state.scene==='expired'){routeBeforeLogin=state.page==='login'?'watch':state.page;navigate('login')}else render()};
$('#reset').onclick=async()=>{if(await clearChartLayout())location.href=location.pathname+'?page=watch'};
function recoverDemo(){state.scene='normal';if(state.page!=='login'||$('#sheet').open)render();else{$('#review-scene').value='normal';header()}paintOperation()}
$('#demo-recover').onclick=recoverDemo;
addEventListener('resize',()=>{if(state.page==='chart'&&!$('#sheet').open)render();positionSheet();paintAlertNotice();paintOperation()});addEventListener('scroll',positionSheet,{passive:true});
addEventListener('popstate',e=>{if($('#sheet').open){closeAll()}navigate(e.state?.page||'watch',false)});
const pageParam=new URLSearchParams(location.search).get('page');if(['watch','chart','alerts','more','center','login'].includes(pageParam))state.page=pageParam;
history.replaceState({page:state.page},'',urlFor(state.page));/* A07 bootstrap is in refinement.js. */
